    def __init__(self):
        super().__init__()
        self.setWindowIcon(app_icon())
        self._vm = MainViewModel(self)
        self._tabs: List[_TraceTab] = []
        self._previous_tab_index: int = -1
        self._tab_switch_guard: bool = False
        self._bound_scene = None
        self._legend_cancel_fn = None
